```javascript
const { Client, GatewayIntentBits, Partials } = require('discord.js');
const { REST } = require('@discordjs/interactions');
const { TOKEN, GUILD_ID } = require('./config.json');

// Create a new client instance
const client = new Client({
    intents: [
        GatewayIntentBits.Guilds,
        GatewayIntentBits.GuildMessages,
        GatewayIntentBits.MessageContent,
        GatewayIntentBits.GuildMembers,
        GatewayIntentBits.GuildModeration,
    ],
    partials: [Partials.Channel, Partials.Message],
});

// Create a REST instance
const rest = new REST({ version: '10' }).setToken(TOKEN);

// Define the commands
const commands = [
    {
        name: 'ban',
        description: 'Ban a user from the server.',
        options: [
            {
                name: 'user',
                description: 'The user to ban.',
                type: 6, // Member
                required: true,
            },
            {
                name: 'reason',
                description: 'Reason for the ban.',
                type: 3, // String
                required: false,
            },
        ],
        defaultMemberPermissions: GatewayIntentBits.ManageMessages,
    },
];

// Fetch the commands from Discord
(async () => {
    try {
        console.log('Started refreshing application (/) commands.');

        await rest.put(
            `/applications/${client.user.id}/guilds/${GUILD_ID}/commands`,
            { body: commands },
        );

        console.log('Successfully reloaded application (/) commands.');
    } catch (error) {
        console.error(error);
    }
})();

// Event handler for ready
client.once('ready', () => {
    console.log(`Logged in as ${client.user.tag}`);
});

// Event handler for slash command interaction
client.on('interactionCreate', async (interaction) => {
    if (!interaction.isChatInputCommand()) return;

    if (interaction.commandName === 'ban') {
        await interaction.deferReply({ ephemeral: true });

        // Check if the user has the required role (moderator or admin)
        const user = interaction.guild.members.cache.get(interaction.options.getMember('user').id);
        const roles = user.roles.cache;
        const hasModeratorRole = roles.some((role) => role.name === 'Moderator');
        const hasAdminRole = roles.some((role) => role.name === 'Admin');

        if (!hasModeratorRole && !hasAdminRole) {
            await interaction.editReply({ content: 'You do not have permission to use this command.' });
            return;
        }

        const reason = interaction.options.getString('reason') || 'No reason provided';

        // Check cooldown
        const banCooldown = 600000; // 10 minutes in milliseconds
        const command = client.commands.get('ban');
        if (command) {
            if (command.cooldowns.has(interaction.user.id)) {
                const remainingTime = command.cooldowns.get(interaction.user.id) - Date.now();
                if (remainingTime > 0) {
                    await interaction.editReply({
                        content: `You are about to reach the cooldown limit. You can use this command again in ${Math.floor(remainingTime / 60000)} minutes and ${Math.floor((remainingTime % 60000) / 1000)} seconds.`,
                    });
                    return;
                }
            }
        }

        // Update the cooldown
        command?.cooldowns.set(interaction.user.id, Date.now() + banCooldown);

        // Ban the user
        await interaction.guild.members.ban(interaction.options.getMember('user').id, { reason });

        await interaction.editReply({ content: `User ${user.user.tag} has been banned. Reason: ${reason}.` });
    }
});

// Run the client
client.login(TOKEN);
```

